import{d as p,C as s,o as d,c as g,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十五章","description":"《正易心法》第十五章——八卦不止，天地雷风：文王周公未当指名物象，故八卦以八德统摄万物，凡健皆乾、凡顺皆坤；一身一物便具八卦之理。","frontmatter":{"title":"正易心法·第十五章","description":"《正易心法》第十五章——八卦不止，天地雷风：文王周公未当指名物象，故八卦以八德统摄万物，凡健皆乾、凡顺皆坤；一身一物便具八卦之理。","category":"guide","aliases":["正易心法第十五章","八卦不止天地雷风","凡健皆乾"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-15.md","filePath":"yijing/zheng-yi-xin-fa/chapter-15.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-15.md"},x=p({...c,setup(u){const i=[{id:"z15-01",label:"一、一身一物据八卦",showLabel:!0,sentences:[["八卦不止，天地雷风。一身一物，便据八卦。"]],note:["八卦不只是天、地、雷、风（等八种具体事物）；任何一个人、任何一件事物，都可以用八卦来分析。（这一句是本章的总纲，也是方法论部分（第十二至十五章）的收束：**由「八字是结构原则」（第十二章）到「万物皆八卦」（本章）。**）"]},{id:"z15-02",label:"二、未当指名物象",showLabel:!0,sentences:[["八卦，文王",{text:"繇辞",glossary:"yaoci"},"，周公爻辞，皆未当指名其物象，以见八卦不止天、地、雷、风、水、火、山、泽，",{text:"无所不统",glossary:"wusuobutong"},"也。"]],note:["文王的卦辞、周公的爻辞，都没有直接指定具体的物象——这正是为了表明八卦不只是天、地、雷、风、水、火、山、泽，而是无所不能统摄的。（**这是一个极重要但容易忽略的论点**：乾的卦辞「元亨利贞」没说「天」，坤的卦辞没说「地」——这不是疏漏，是**故意留白**。一旦说「乾只是天」，乾就被限制死了。）"]},{id:"z15-03",label:"三、八德统摄万物",showLabel:!0,sentences:[["是故凡天下之所谓健者，皆乾也。顺者，皆坤也。动者，皆震也。入者，皆巽也。陷者，皆坎也。丽者，皆离也。止者，皆艮也。说者，皆兑也。"]],note:["因此，凡是天下一切具有刚健特质的，都是乾；柔顺的，都是坤；动的，都是震；渗入的，都是巽；陷溺的，都是坎；附丽的，都是离；停止的，都是艮；喜悦散布的，都是兑。（八德统摄：**天只是「健」的最典型代表，雷只是「动」的最典型代表**——以此类推。这正是第十二章「八字是结构原则」的全面落实：不是「乾＝天」，而是「凡健皆乾」。）"]},{id:"z15-04",label:"四、一身一物便具",showLabel:!0,sentences:[["一身一物，便具此八卦之理。"]],note:["任何一个人、任何一件事物，都具备这八卦的道理。（注意这里的**内外之别**：不是说「八卦可以解释万物」（这还是外在的工具论），而是说「**万物本来就具备八卦之理**」（这是内在的结构论）。这与第五章「合为自然」完全呼应：八卦不是人发明的分析工具，而是万物本来的结构，圣人只是「识取自然」。）"]},{id:"z15-05",label:"五、宣父止以八物",showLabel:!0,sentences:[["然",{text:"宣父",glossary:"xuanfu"},"止以八物云者，特举其大者为",{text:"宗本",glossary:"zongben"},"，姑以入《易》，以便学者耳。"]],note:["然而孔子只用八种具体事物来说，是特别举出最典型的作为根本纲领，姑且用来引导学者入门、方便学者理解罢了。（**这是全书对孔子最温和也最精准的一个评价**：八物不是错误的，而是「入门级」的。就像学数学：小学用具体数字（1+1=2），中学用抽象符号（a+b=c），大学用普遍原则。**孔子的八物是台阶——台阶是用来走上去的，不是用来站在上面不动的。**「宣父」是唐代追谥孔子的尊称。）"]}],o=[{id:"yaoci",term:"繇辞",pinyin:"yáo cí",meaning:"繇通「爻」，此处指文王所作的卦辞。"},{id:"wusuobutong",term:"无所不统",pinyin:"wú suǒ bù tǒng",meaning:"没有什么不能统摄。八卦的义理可以统摄万事万物。"},{id:"xuanfu",term:"宣父",pinyin:"xuān fǔ",meaning:"孔子的尊称。唐代追谥孔子为「宣父」。"},{id:"zongben",term:"宗本",pinyin:"zōng běn",meaning:"根本、纲领。孔子举八物是作为入门的总纲。"}];return(b,n)=>{const l=s("DaoTextReading"),r=s("DaoKeywordCards");return d(),g("div",null,[n[0]||(n[0]=t("",23)),e(l,{colophon:"八卦不止 · 未指物象 · 凡健皆乾 · 一身一物",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十五章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本（「繇辞」「宣父」皆随底本），不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(r,{items:[{term:"未当指名物象",pinyin:["wèi","zhǐ"],meaning:"文王卦辞、周公爻辞都没有直接指定物象——不是疏漏，是故意留白，保持八卦无限的统摄力。"},{term:"凡健皆乾",pinyin:["fán","jiàn"],meaning:"八德统摄：凡天下一切刚健的皆是乾，柔顺的皆是坤……天只是「健」的最典型代表。"},{term:"一身一物",pinyin:["yī","shēn"],meaning:"不是说「八卦可以解释万物」（外在工具论），而是说「万物本来就具备八卦之理」（内在结构论）。"},{term:"宗本",pinyin:["zōng","běn"],meaning:"根本、纲领。孔子举八物是作为入门的总纲，「以便学者」——台阶是用来走上去的。"},{term:"宣父",pinyin:["xuān","fǔ"],meaning:"孔子的尊称。麻衣评孔子止以八物言之，只是「特举其大者为宗本」，非批评孔子。"}]}),n[3]||(n[3]=t("",26))])}}});export{y as __pageData,x as default};
